/*
 * Duke — modelo 3D feito só com código Three.js (r128 ou mais novo)
 * (6.6.7) No jogo: o peixe lendário misterioso do lago, só no dia 13 de maio (a data do aparelho). Ver pesca.js (cenaDuke).
 * Gerado pelo Conversor FBX → Three.js em 02/11/2026, a partir de "Duke.fbx".
 *
 * Tem: 1 malha · 1432 vértices · 716 triângulos · 0 ossos · 4 materiais · 0 texturas
 * Sem animações.
 *
 * COMO USAR (no index.html, DEPOIS do three.min.js):
 *   <script src="Duke.js"></script>
 *   const m = criarDuke();          // cada chamada monta um modelo novo (geometrias e texturas são reaproveitadas)
 *   cena.add(m.raiz);                   // mexa em m.raiz.position / m.raiz.rotation.y como nos bonecos do jogo
 *   // no loop do jogo, todo quadro:
 *   m.atualizar(dt);                    // dt em segundos
 */
(function (global) {
  'use strict';
  const THREE = global.THREE;
  if (!THREE) throw new Error('Duke.js: carregue o three.min.js antes deste arquivo.');

  // lê os dados guardados no arquivo (texto base64 ou lista de números) como arrays do three.js
  const bytes = (s) => { const b = atob(s), u = new Uint8Array(b.length); for (let i = 0; i < b.length; i++) u[i] = b.charCodeAt(i); return u.buffer; };
  const f32 = (d) => (typeof d === 'string' ? new Float32Array(bytes(d)) : new Float32Array(d));
  const u16 = (d) => (typeof d === 'string' ? new Uint16Array(bytes(d)) : new Uint16Array(d));
  const u32 = (d) => (typeof d === 'string' ? new Uint32Array(bytes(d)) : new Uint32Array(d));
  const u8 = (d) => (typeof d === 'string' ? new Uint8Array(bytes(d)) : new Uint8Array(d));
  const i16 = (d) => (typeof d === 'string' ? new Int16Array(bytes(d)) : new Int16Array(d));
  const i8 = (d) => (typeof d === 'string' ? new Int8Array(bytes(d)) : new Int8Array(d));
  const i32 = (d) => (typeof d === 'string' ? new Int32Array(bytes(d)) : new Int32Array(d));

  // ================================================================ 1. AJUSTE
  // Feito no conversor: tamanho original, pés no chão (y = 0). Pode mudar à vontade.
  const AJUSTE = { escala: 1, giroY: 0, alturaY: 127.197174 };

  // ================================================================ 2. TEXTURAS
  const TEXTURAS = [];

  // ================================================================ 3. MATERIAIS
  // cores em hexadecimal (como no jogo); mapas apontam para o número da textura acima
  const MATERIAIS = [
    { tipo: 'MeshPhongMaterial', name: "Material", color: 0x00c42a, emissive: 0xffffff, specular: 0x00c42a, shininess: 0, emissiveIntensity: 0, reflectivity: 0, bumpScale: 0 }, // 0
    { tipo: 'MeshPhongMaterial', name: "Material.001", color: 0x000000, emissive: 0xffffff, specular: 0x000000, shininess: 25, emissiveIntensity: 0, reflectivity: 0, bumpScale: 0 }, // 1
    { tipo: 'MeshPhongMaterial', name: "Material.002", color: 0xa8ff10, emissive: 0xffffff, specular: 0xa8ff10, shininess: 25, emissiveIntensity: 0, reflectivity: 0, bumpScale: 0 }, // 2
    { tipo: 'MeshPhongMaterial', name: "Material.003", color: 0x0c2993, emissive: 0xffffff, specular: 0x0c2993, shininess: 25, emissiveIntensity: 0, reflectivity: 0, bumpScale: 0 }, // 3
  ];

  // ================================================================ 4. GEOMETRIAS
  // atributos: [tamanho de cada item, dados, normalizado]. grupos: [início, quantidade, material]
  const GEOMETRIAS = [
    { // 0: "Cube.001" — 1432 vértices, 716 triângulos
      nome: "Cube.001",
      indice: u16(''),
      atributos: {
        position: [3, f32('')],
        normal: [3, f32('')],
        uv: [2, f32('')],
      },
      grupos: [[0,906,0], [906,6,3], [912,42,0], [954,12,3], [966,24,0], [990,6,3], [996,42,0], [1038,12,3], [1050,24,0], [1074,6,3], [1080,42,0], [1122,12,3], [1134,18,0], [1152,72,1], [1224,60,2], [1284,36,0], [1320,36,1], [1356,66,0], [1422,6,3], [1428,42,0], [1470,12,3], [1482,24,0], [1506,6,3], [1512,42,0], [1554,12,3], [1566,24,0], [1590,6,3], [1596,42,0], [1638,12,3], [1650,18,0], [1668,72,1], [1740,60,2], [1800,36,0], [1836,36,1], [1872,66,0], [1938,6,3], [1944,12,0], [1956,6,3], [1962,12,0], [1974,6,3], [1980,12,0], [1992,6,3], [1998,12,0], [2010,6,3], [2016,12,0], [2028,6,3], [2034,12,0], [2046,6,3], [2052,12,0], [2064,6,3], [2070,12,0], [2082,6,3], [2088,12,0], [2100,6,3], [2106,12,0], [2118,6,3], [2124,12,0], [2136,6,3], [2142,6,0]],
    },
  ];

  // ================================================================ 5. OBJETOS E OSSOS
  // [nome, tipo, pai, posição, rotação (quaternion x,y,z,w), escala, extra]   (null = padrão)
  // a ordem é a da árvore do FBX: o pai sempre vem antes dos filhos
  const NOS = [
    ["", 'grupo', -1], // 0
    ["Cube001", 'malha', 0, null, null, null, { geo: 0, mat: [0,1,2,3] }], // 1
  ];
  const ESQUELETOS = [];

  // ================================================================ 6. ANIMAÇÕES
  // cada faixa: ['Osso.propriedade', tipo, tempos (s), valores, interpolação]
  const ANIMACOES = [
  ];

  // ================================================================ 7. MONTAGEM (não precisa mexer daqui para baixo)
  const MAPAS = ['map', 'normalMap', 'bumpMap', 'specularMap', 'emissiveMap', 'alphaMap', 'aoMap', 'lightMap', 'displacementMap', 'roughnessMap', 'metalnessMap'];
  const FAIXA = { vector: THREE.VectorKeyframeTrack, quaternion: THREE.QuaternionKeyframeTrack, number: THREE.NumberKeyframeTrack, color: THREE.ColorKeyframeTrack };
  let comum = null;   // geometrias, materiais, texturas e animações: feitos UMA vez e usados por todos os modelos

  function prepararComum() {
    if (comum) return comum;
    const carregador = new THREE.TextureLoader();
    const texturas = TEXTURAS.map((t) => {
      const tex = carregador.load(t.imagem);
      tex.name = t.nome;
      if (t.wrapS != null) { tex.wrapS = t.wrapS; tex.wrapT = t.wrapT; }
      if (t.repeat) tex.repeat.fromArray(t.repeat);
      if (t.offset) tex.offset.fromArray(t.offset);
      if (t.rotation) tex.rotation = t.rotation;
      if (t.flipY === false) tex.flipY = false;
      if (t.encoding != null) tex.encoding = t.encoding;
      if (t.pixelada) { tex.magFilter = THREE.NearestFilter; tex.minFilter = THREE.NearestFilter; tex.generateMipmaps = false; }
      return tex;
    });
    const materiais = MATERIAIS.map((m) => {
      const mat = new THREE[m.tipo]();
      for (const k in m) {
        if (k === 'tipo') continue;
        const v = m[k];
        if (MAPAS.indexOf(k) >= 0) mat[k] = texturas[v] || null;
        else if (mat[k] && mat[k].isColor) mat[k].setHex(v);
        else if (mat[k] && mat[k].isVector2) mat[k].fromArray(v);
        else mat[k] = v;          // skinning / morphTargets: o r128 precisa; nas versões novas não atrapalha
      }
      return mat;
    });
    const geometrias = GEOMETRIAS.map((g) => {
      const geo = new THREE.BufferGeometry();
      geo.name = g.nome;
      for (const k in g.atributos) { const a = g.atributos[k]; geo.setAttribute(k, new THREE.BufferAttribute(a[1], a[0], !!a[2])); }
      if (g.indice) geo.setIndex(new THREE.BufferAttribute(g.indice, 1));
      for (const x of g.grupos || []) geo.addGroup(x[0], x[1], x[2]);
      if (g.morph) {
        for (const k in g.morph) geo.morphAttributes[k] = g.morph[k].map((x) => { const a = new THREE.BufferAttribute(x[1], 3); a.name = x[0]; return a; });
        geo.morphTargetsRelative = !!g.morphRelativo;
      }
      geo.computeBoundingBox(); geo.computeBoundingSphere();
      return geo;
    });
    const animacoes = {};
    for (const a of ANIMACOES) {
      animacoes[a.nome] = new THREE.AnimationClip(a.nome, a.duracao, a.faixas.map((f) => new FAIXA[f[1]](f[0], f[2], f[3], f[4])));
    }
    comum = { texturas, materiais, geometrias, animacoes };
    return comum;
  }

  function criarDuke(opcoes) {
    opcoes = opcoes || {};
    const C = prepararComum();
    const raiz = new THREE.Group();
    raiz.name = "Duke";
    const ajuste = new THREE.Group();            // escala / giro / altura do conversor ficam aqui
    ajuste.name = 'ajuste';
    ajuste.scale.setScalar(AJUSTE.escala);
    ajuste.rotation.y = AJUSTE.giroY;
    ajuste.position.y = AJUSTE.alturaY;
    raiz.add(ajuste);
    const objetos = NOS.map((n) => {
      const tipo = n[1], ex = n[6] || {};
      let o;
      if (tipo === 'osso') o = new THREE.Bone();
      else if (tipo === 'malha' || tipo === 'malhaPele') {
        const mat = Array.isArray(ex.mat) ? ex.mat.map((i) => C.materiais[i]) : C.materiais[ex.mat];
        o = tipo === 'malhaPele' ? new THREE.SkinnedMesh(C.geometrias[ex.geo], mat) : new THREE.Mesh(C.geometrias[ex.geo], mat);
        o.castShadow = !!(opcoes.sombras || ex.castShadow);
        o.receiveShadow = !!(opcoes.sombras || ex.receiveShadow);
        if (ex.frustumCulled === false) o.frustumCulled = false;
        if (ex.renderOrder) o.renderOrder = ex.renderOrder;
      } else o = new THREE.Group();
      o.name = n[0];
      if (n[3]) o.position.fromArray(n[3]);
      if (n[4]) o.quaternion.fromArray(n[4]);
      if (n[5]) o.scale.fromArray(n[5]);
      if (ex.visible === false) o.visible = false;
      return o;
    });
    NOS.forEach((n, i) => (n[2] < 0 ? ajuste : objetos[n[2]]).add(objetos[i]));
    raiz.updateMatrixWorld(true);
    for (const e of ESQUELETOS) {
      const ossos = e.ossos.map((i) => objetos[i]);
      const inversas = ossos.map((_, k) => new THREE.Matrix4().fromArray(e.inversas, k * 16));
      const malha = objetos[e.malha];
      if (e.bindMode) malha.bindMode = e.bindMode;
      malha.bind(new THREE.Skeleton(ossos, inversas), new THREE.Matrix4().fromArray(e.bind));
    }
    const ossos = {};
    for (const o of objetos) if (o.isBone && !(o.name in ossos)) ossos[o.name] = o;
    const malhas = objetos.filter((o) => o.isMesh);
    const mixer = new THREE.AnimationMixer(raiz);
    let atual = null;

    // toca uma animação pelo nome. op: { repetir: true, transicao: 0.2 (s), velocidade: 1 }
    function tocar(nome, op) {
      op = op || {};
      const clipe = C.animacoes[nome];
      if (!clipe) { console.warn("Duke" + ': animação não existe: ' + nome); return null; }
      const acao = mixer.clipAction(clipe);
      const repetir = op.repetir !== false;
      acao.setLoop(repetir ? THREE.LoopRepeat : THREE.LoopOnce, Infinity);
      acao.clampWhenFinished = !repetir;
      acao.timeScale = op.velocidade != null ? op.velocidade : 1;
      if (acao === atual) return acao;
      acao.reset().play();
      const t = op.transicao != null ? op.transicao : 0.2;
      if (atual) { if (t > 0) atual.crossFadeTo(acao, t, false); else atual.stop(); }
      atual = acao;
      return acao;
    }
    return {
      raiz, ajuste, objetos, ossos, malhas, mixer, animacoes: C.animacoes,
      tocar,
      parar() { mixer.stopAllAction(); atual = null; },
      atualizar(dt) { mixer.update(dt); },
      osso(nome) { return ossos[nome]; },
      get animacaoAtual() { return atual ? atual.getClip().name : null; },
      descartar() { mixer.stopAllAction(); mixer.uncacheRoot(raiz); if (raiz.parent) raiz.parent.remove(raiz); },
    };
  }
  criarDuke.animacoes = ANIMACOES.map((a) => a.nome);
  criarDuke.ossos = NOS.filter((n) => n[1] === 'osso').map((n) => n[0]);
  // libera da memória o que é comum a todos (só quando nenhum modelo deste tipo estiver na cena)
  criarDuke.liberarMemoria = function () {
    if (!comum) return;
    comum.geometrias.forEach((g) => g.dispose()); comum.materiais.forEach((m) => m.dispose()); comum.texturas.forEach((t) => t.dispose());
    comum = null;
  };
  global.criarDuke = criarDuke;
  // (6.6.7) registrado como "fase" só para o jogo saber baixar este arquivo (o pesca.js baixa no dia 13 de maio: FutebolJS.carregarFase('duke'))
  if (global.FutebolJS && global.FutebolJS.registrarFase) global.FutebolJS.registrarFase({ id: 'duke', nome: 'Duke', iniciar: async () => {}, criar: criarDuke });
})(typeof window !== 'undefined' ? window : globalThis);
